import{d as u,C as t,o as m,c,j as a,a as o,E as s,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十七章","description":"从无为而无不为与万物自化，理解以无名之朴安定争欲、使天下自定。","frontmatter":{"title":"道德经第三十七章","description":"从无为而无不为与万物自化，理解以无名之朴安定争欲、使天下自定。","category":"guide","aliases":["道德经第三十七章","老子第三十七章","dao de jing chapter 37"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-37.md","filePath":"daoism/dao-de-jing/chapter-37.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-37.md"},w=u({...g,setup(b){const n=[{id:"non-imposition-and-accomplishment",label:"道常无为而无不为",showLabel:!0,sentences:[["道常",{text:"无为",glossary:"wuwei"},"而",{text:"无不为",glossary:"wubuwei"},"。"]],note:["【白话】道恒常不以私意强作，而万物又无不由它得到成就。前后两面相连：不妄加干预，与使事物得以生成、成全并不冲突。","【王弼注择要】「顺自然也。」王弼以此注无为；接着说「万物无不由为以治以成之也」，说明无不为落在万物的治理与成就。","【读法】无不为不作自己事事包办、无所不能的夸大说法。无为也应结合相应职责判断，不能用来回避应当承担的照顾和行动。"]},{id:"rulers-and-spontaneous-transformation",label:"侯王若能守之，万物将自化",showLabel:!0,sentences:[[{text:"侯王",glossary:"houwang"},"若能守之，万物将",{text:"自化",glossary:"zihua"},"。"]],note:["【白话】侯王若能守住无为之道，万物就将依其本性自行变化、成长。治理者的取向，是给这种变化留下空间，不把每一处变化都变成个人意志的作品。","【读法】之承上文之道，与第三十二章侯王守朴相通。这里是本章提出的理想治理关系，自化并非忽略现实条件后就必然发生的结果。"]},{id:"settling-emergent-desire",label:"吾将镇之以无名之朴",showLabel:!0,sentences:[["化而欲",{text:"作",glossary:"zuo"},"，吾将",{text:"镇",glossary:"zhen"},"之以",{text:"无名",glossary:"wuming"},"之",{text:"朴",glossary:"pu"},"。"]],note:["【白话】在变化中，若争求造作的欲望又要兴起，我便以无名、未分的真朴使它安定。所用的方向是收回争逐名目的心，而非再添一层强制争胜。","【王弼注择要】「化而欲作，作欲成也。」注于无名之朴又说「不为主也」，使镇之与不自居为主相连。","【读法】欲作可以从欲望将兴起读；王注的作欲成也另提示造作将成的意味。本页将其限定在争逐、强作的语境，不把万物一切活动都判为应受压制。"]},{id:"simplicity-and-settled-order",label:"不欲以静，天下将自定",showLabel:!0,sentences:[["镇之以无名之朴，夫亦将",{text:"无欲",glossary:"wuyu"},"。"],["不欲以",{text:"静",glossary:"jing"},"，天下将",{text:"自定",glossary:"ziding"},"。"]],note:["【白话】以无名之朴使之安定，争求的欲望也将渐息。不再为这种欲求所驱而归于安静，天下便将自行安定。末段把镇之的落点收回无欲与静。","【王弼注择要】「无欲竞也。」本页据此将无欲着重理解为不争竞，不把人的基本生计、合理愿望一并取消。","【读法】本站保留第二次镇之以无名之朴；所据录文这里作无名之朴夫亦将无欲。重复句与注释在不同传本中的情况仍须分别核对，不据录文默删本站文字。"]}],r=[{id:"wuwei",term:"无为",sense:1},{id:"wubuwei",term:"无不为",sense:1},{id:"houwang",term:"侯王",sense:1},{id:"zihua",term:"自化",sense:1},{id:"zuo",term:"作",sense:1},{id:"zhen",term:"镇",sense:1},{id:"wuming",term:"无名",sense:2},{id:"pu",term:"朴",sense:2},{id:"wuyu",term:"无欲",sense:1},{id:"jing",term:"静",sense:1},{id:"ziding",term:"自定",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十七章",tabindex:"-1"},[o("道德经第三十七章 "),a("a",{class:"header-anchor",href:"#道德经第三十七章","aria-label":'Permalink to "道德经第三十七章"'},"​")],-1)),s(i,{title:"无为怎样连到自化，又为什么仍要镇之",summary:"作为通行本《道经》的收束，本章先说无为而无不为，再写侯王守道与万物自化；自化中若争欲兴起，便以无名之朴安定，最后归于不欲、静与自定。",points:[{label:"先读",text:"依王弼顺自然解释无为，成全万物不等于由自己包办一切。"},{label:"再辨",text:"自化中仍可能欲作，需辨无名之朴如何安定而不自居主宰。"},{label:"后看",text:"将不欲、静、自定连起来，读出不以竞争性欲望不断扰动天下的取向。"}],hint:"本章的镇取安定、镇抚义，连王弼不为主也理解；作取兴起义，不把一般学习、创造欲望都归为应当消除。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"道常无为而无不为。",tone:"不强作而能成全",guide:"依王弼，把顺自然与万物由之以成连起来，不以包办一切解释无不为。"},{text:"化而欲作，吾将镇之以无名之朴。",tone:"自化中仍须辨欲作",guide:"看见变化中的争欲，以真朴安定；不为主仍是解释镇之的重要约束。"},{text:"不欲以静，天下将自定。",tone:"安定不只靠加码干预",guide:"先察在上者是否不断制造争欲，再谈天下的自定。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:r}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么自化之后又出现欲作" tabindex="-1">象：为什么自化之后又出现欲作？ <a class="header-anchor" href="#象-为什么自化之后又出现欲作" aria-label="Permalink to &quot;象：为什么自化之后又出现欲作？&quot;">​</a></h3><p>本章没有把自化写成从此永无波动。变化中仍可能兴起争求和造作，因此后半章提出镇之以无名之朴，再用无欲、静说明安定的方向。</p><h3 id="理-镇之会不会与无为冲突" tabindex="-1">理：镇之会不会与无为冲突？ <a class="header-anchor" href="#理-镇之会不会与无为冲突" aria-label="Permalink to &quot;理：镇之会不会与无为冲突？&quot;">​</a></h3><p>若镇之被理解成以个人意志全面控制万物，便难与前文无为相贯。王弼在此说不为主也，给出一条读法：以不争名、不增欲的真朴安定，而不是自居主宰、替一切变化定型。</p><h3 id="用-现代协作如何借鉴自化与自定" tabindex="-1">用：现代协作如何借鉴自化与自定？ <a class="header-anchor" href="#用-现代协作如何借鉴自化与自定" aria-label="Permalink to &quot;用：现代协作如何借鉴自化与自定？&quot;">​</a></h3><p>可以先给参与者明确的职责、适当资源与自主空间，减少因个人好恶不断改动方向；当竞争和炫示开始扰乱合作时，回到共同需要与基本规则。这样的类比仍须保留必要的介入与责任。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>减少由自己制造的扰动。</strong> 频繁改变指标、不断刺激比较，可能使原本能合作的人转向争逐。发现这种情况时，先检视决策者自身的要求。</p><p><strong>出现争欲时回到基本需要。</strong> 面对资源、名号与表现的竞争，把问题重新写成谁需要什么、怎样共同完成，而不只再添一轮排名与奖惩。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我说希望事情自行运转时，是否提供了必要条件？我又在哪些地方因自己的欲望而反复扰动它？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「镇之以无名之朴，夫亦将无欲」的重复句；所据 HFL 录文该处作「无名之朴夫亦将无欲」。本页不将录文注语吾将镇之等混充为本站第二次经句的逐字依据。</li><li>镇与录文鎭按简繁字形对应；无欲以王弼无欲竞也说明，镇之连不为主也解释。</li><li>此为通行本上篇《道经》末章；第三十八章起为《德经》，后续古注来源随之转入所据卷三。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，012a</a>。</p>',15))])}}});export{_ as __pageData,w as default};
